const out = wb.getWorksheet('Output Required');
const data = wb.getRange('Main!A2:J11').getValues();
const names = data.slice(0,5).map(r=>r[7]);
const copy = async (dst, src) => { await out.getRange(dst).copyFrom(wb.getRange(src)); };
await copy('A1:G1','Main!A1:G1');
for (const c of ['H','I','J','K','L','M']) await copy(c+'1','Main!H1');
const staff = [...new Set(data.map(r=>r[0]))];
for (let i=0;i<staff.length;i++){
  const rows = data.filter(r=>r[0]===staff[i]);
  const srcRow = data.indexOf(rows[0])+2;
  const n = i+2;
  await copy(`A${n}:G${n}`,`Main!A${srcRow}:G${srcRow}`);
  for (const c of ['H','I','J','K','L','M']) await copy(`${c}${n}`,`Main!I${srcRow}`);
  names.forEach((nm,j)=>{ out.getRange(['H','I','J','K','L'][j]+n).setValue(rows.find(r=>r[7]===nm)[8]); });
  out.getRange('M'+n).setValue(`=SUM(H${n}:L${n})`);
}
names.forEach((nm,j)=>out.getRange(['H','I','J','K','L'][j]+'1').setValue(nm));
out.getRange('M1').setValue('Total');
out.getRange('A1:M3').autoFit();
